SP=/tmp/claude-0/-home-user-sandbox/2a3c0c61-b148-57c8-aa69-8b7c36824c11/scratchpad
cat > "$SP/scripts/view.py" <<'EOF'
"""Print a compact view of JSONL events in a line range: view.py FILE START END [WIDTH]"""
import json, sys
path, start, end = sys.argv[1], int(sys.argv[2]), int(sys.argv[3])
width = int(sys.argv[4]) if len(sys.argv) > 4 else 400
def short(s, w=width):
    s = " ".join(str(s).split())
    return s if len(s) <= w else s[:w] + f"...(+{len(s)-w})"
with open(path, encoding="utf-8", errors="replace") as fh:
    for n, line in enumerate(fh, 1):
        if n < start: continue
        if n > end: break
        try:
            ev = json.loads(line)
        except ValueError:
            print(f"L{n}: <unparseable>"); continue
        t = ev.get("type"); st = ev.get("subtype") or ""
        ts = (ev.get("timestamp") or "")[11:19]
        msg = ev.get("message") if isinstance(ev.get("message"), dict) else {}
        content = msg.get("content")
        head = f"L{n} {ts} {t}{'/'+st if st else ''}"
        if t in ("user", "assistant"):
            if isinstance(content, str):
                print(f"{head} TEXT: {short(content)}")
            elif isinstance(content, list):
                for b in content:
                    if not isinstance(b, dict): continue
                    bt = b.get("type")
                    if bt == "text":
                        print(f"{head} text: {short(b.get('text'))}")
                    elif bt == "thinking":
                        print(f"{head} thinking: {short(b.get('thinking'), 200)}")
                    elif bt == "tool_use":
                        print(f"{head} TOOL_USE {b.get('name')} id={b.get('id','')[-6:]}: {short(json.dumps(b.get('input'), ensure_ascii=False))}")
                    elif bt == "tool_result":
                        c = b.get("content")
                        if isinstance(c, list):
                            c = " ".join(x.get("text", "") if isinstance(x, dict) else str(x) for x in c)
                        print(f"{head} RESULT id={b.get('tool_use_id','')[-6:]} err={b.get('is_error', False)}: {short(c)}")
                    else:
                        print(f"{head} {bt}")
            else:
                print(f"{head} (no content)")
        elif t == "attachment":
            a = ev.get("attachment") or {}
            print(f"{head} attachment {a.get('type') if isinstance(a, dict) else ''}: {short(json.dumps(a, ensure_ascii=False), 200)}")
        elif t == "system":
            print(f"{head}: {short(json.dumps({k: v for k, v in ev.items() if k not in ('uuid','parentUuid','sessionId','cwd','gitBranch','version','userType','entrypoint')}, ensure_ascii=False), 300)}")
        else:
            print(f"{head}: {short(json.dumps({k: v for k, v in ev.items() if k not in ('uuid','parentUuid','sessionId')}, ensure_ascii=False), 200)}")
EOF
dir=$(cat "$SP/dir.txt"); S=$dir/transcripts/5cf280aa-dd29-5863-8c3f-bc3cd0eec352.jsonl
python3 -I "$SP/scripts/view.py" "$S" 300 360 500

